	@Test
	public void mappingParameterizedOperatorsKeepCorrelatedEvaluation() {
		ZeroLengthPath path = new ZeroLengthPath(Var.of("x"), Var.of("r"));

		assertFalse(QueryEvaluationUtility.permitsBindingInjection(path, Set.of("x")),
				"a seeded zero-length path matches terms absent from the graph (GH-3053) — injection is not a "
						+ "selection over independent evaluation, so injection-introducing rewrites must be rejected");
		assertTrue(QueryEvaluationUtility.usesMappingParameterizedEvaluation(path),
				"correlated per-input evaluation is the path's defined semantics — physical strategies keep the "
						+ "bind-join path instead of rerouting through independent-evaluation replay");
		assertTrue(QueryEvaluationUtility.usesMappingParameterizedEvaluation(
				new Join(pattern("a", "p", "b"), path.clone())),
				"the contract is contagious: any subtree containing such an operator stays correlated");
		assertFalse(QueryEvaluationUtility.usesMappingParameterizedEvaluation(pattern("a", "p", "b")));
	}

	@Test
	public void sameGroupFilterInputsAreIndexedByTheirExactJoinOwners() {
		Filter condition = new Filter(new SingletonSet(), new And(new Bound(Var.of("x")), new Bound(Var.of("z"))));
		Join inner = new Join(pattern("z", "q", "o"), condition);
		Join outer = new Join(pattern("x", "p", "s"), inner);

		assertTrue(QueryEvaluationUtility.requiresScopedFilterInput(inner));
		assertTrue(QueryEvaluationUtility.requiresScopedFilterInput(outer));
		inner.setVariableScopeChange(true);
		assertTrue(QueryEvaluationUtility.requiresScopedFilterInput(inner));
		assertFalse(QueryEvaluationUtility.requiresScopedFilterInput(outer));
	}

	@Test
	public void nestedFiltersKeepTheirDistinctJoinOwnersAcrossASubqueryBoundary() {
		Filter innerFilter = new Filter(new SingletonSet(), new Bound(Var.of("inner")));
		Join innerOwner = new Join(pattern("outer", "innerPredicate", "inner"), innerFilter);
		Projection subquery = new Projection(innerOwner,
				new ProjectionElemList(new ProjectionElem("outer")), true);
		Filter outerFilter = new Filter(new SingletonSet(), new Bound(Var.of("outer")));
		Join outerOwner = new Join(subquery, outerFilter);

		List<BindingScopePolicy.FilterInputEdge> innerEdges = BindingScopePolicy.filterInputEdges(innerFilter);
		List<BindingScopePolicy.FilterInputEdge> outerEdges = BindingScopePolicy.filterInputEdges(outerFilter);

		assertEquals(1, innerEdges.size());
		assertSame(innerOwner, innerEdges.get(0).owner());
		assertEquals(Set.of("inner"), innerEdges.get(0).names());
		assertEquals(1, outerEdges.size());
		assertSame(outerOwner, outerEdges.get(0).owner());
		assertEquals(Set.of("outer"), outerEdges.get(0).names());
	}

	@Test
	public void refreshRebuildsPreparedFilterStructuralFacts() {
		Filter filter = new Filter(new SingletonSet(), new Bound(Var.of("before")));
		Join owner = new Join(pattern("before", "predicate", "object"), filter);
		QueryEvaluationUtility.QuerySafetySnapshot snapshot = QueryEvaluationUtility.querySafetySnapshot(owner);

		assertTrue(snapshot.requiresScopedFilterInput(owner));
		assertTrue(snapshot.mayIntroduceFilterInput(filter, Set.of("before"), false));

		filter.setCondition(new Bound(Var.of("after")));
		snapshot.refreshFrom(filter);

		assertFalse(snapshot.requiresScopedFilterInput(owner));
		assertFalse(snapshot.mayIntroduceFilterInput(filter, Set.of("before"), false));
		assertTrue(snapshot.mayIntroduceFilterInput(filter, Set.of("after"), false));
	}

