	@Test
	public void replayPartitionFactsFollowScopedFilterAndGraphInputs() {
		Filter filter = new Filter(new SingletonSet(), new Bound(Var.of("x")));
		Join join = new Join(pattern("x", "p", "o"), filter);

		assertTrue(QueryEvaluationUtility.requiresBindingFrameReplayPartition(join));
		assertTrue(QueryEvaluationUtility.requiresBindingFrameReplayPartition(filter));
		assertFalse(QueryEvaluationUtility.requiresBindingFrameReplayPartition(filter.getArg()));
		filter.setVariableScopeChange(true);
		assertFalse(QueryEvaluationUtility.requiresBindingFrameReplayPartition(join));

		Projection graphProjection = new Projection(new SingletonSet());
		graphProjection.setInheritedGraphParameter("privateGraph");
		assertTrue(QueryEvaluationUtility.requiresBindingFrameReplayPartition(graphProjection));
		assertFalse(QueryEvaluationUtility.requiresBindingFrameReplayPartition(graphProjection.getArg()));
	}

