	@Test
	public void existsValuesColumnCanReadAnInjectedBindingWithoutAVarNode() {
		MapBindingSet row = new MapBindingSet();
		row.addBinding("x", SimpleValueFactory.getInstance().createLiteral("left"));
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of("x"));
		values.setBindingSets(List.of(row));
		Filter filter = new Filter(new SingletonSet(), new Exists(values));

		assertFalse(QueryEvaluationUtility.permitsBindingInjection(filter, Set.of("x")),
				"an EXISTS VALUES column can correlate with an injected binding without a Var child");
	}

	private static final class OpaqueValueExpr extends AbstractQueryModelNode implements ValueExpr {
		@Override
		public <X extends Exception> void visit(QueryModelVisitor<X> visitor) throws X {
			visitor.meetOther(this);
		}

		@Override
		public <X extends Exception> void visitChildren(QueryModelVisitor<X> visitor) {
		}

		@Override
		public void replaceChildNode(QueryModelNode current, QueryModelNode replacement) {
			throw new IllegalArgumentException("Opaque value expression has no children");
		}

		@Override
		public OpaqueValueExpr clone() {
			return (OpaqueValueExpr) super.clone();
		}
	}
